const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const regions = [
      { name: 'EastMidlands', geom: ee.Geometry.Rectangle([-1.9, 52.7, -0.5, 53.5]) },
      { name: 'NE_England', geom: ee.Geometry.Rectangle([-2.2, 54.7, -1.2, 55.4]) },
      { name: 'E_Scotland', geom: ee.Geometry.Rectangle([-3.5, 56.5, -2.0, 57.4]) }
    ];
    const obsOctStart = ee.Date('2023-10-01');
    const obsOctEnd = ee.Date('2023-11-01'); // exclusive
    const obsJanStart = ee.Date('2024-01-01');
    const obsJanEnd = ee.Date('2024-01-05'); // exclusive (1-4)
    const years = ee.List.sequence(1991, 2020);
    const maxPixels = 1e9;

    // Dataset configs
    const datasets = [
      { key: 'CHIRPS', id: 'UCSB-CHG/CHIRPS/DAILY', band: 'precipitation', mmMultiplier: 1, scale: 5500 },
      { key: 'ERA5-LAND', id: 'ECMWF/ERA5_LAND/DAILY_AGGR', band: 'total_precipitation_sum', mmMultiplier: 1000, scale: 9000 }
    ];

    // Helper to get collection size
    const colSize = async (ds, start, end) =>
      await ee.ImageCollection(ds.id).filterDate(start, end).size().getInfo();

    // Choose dataset with fallback
    let ds = datasets[0];
    let sizeOct = await colSize(ds, obsOctStart, obsOctEnd);
    let sizeJan = await colSize(ds, obsJanStart, obsJanEnd);
    if (sizeOct === 0 || sizeJan === 0) {
      ds = datasets[1];
      sizeOct = await colSize(ds, obsOctStart, obsOctEnd);
      sizeJan = await colSize(ds, obsJanStart, obsJanEnd);
      if (sizeOct === 0 || sizeJan === 0) {
        console.log('Obs Oct imgs:', sizeOct, 'Jan1-4 imgs:', sizeJan);
        console.log('C1');
        return;
      }
    }

    // Functions to build summed precip images in mm
    const sumImage = (start, end) => {
      const col = ee.ImageCollection(ds.id)
        .filterDate(start, end)
        .select(ds.band)
        .map(img => img.multiply(ds.mmMultiplier).rename('precip'));
      return ee.Image(col.sum().rename('precip'));
    };
    const climoMeanImage = (monthStart, dayStart, monthEnd, dayEnd) => {
      const imgs = years.map(y => {
        const start = ee.Date.fromYMD(ee.Number(y), monthStart, dayStart);
        const end = ee.Date.fromYMD(ee.Number(y), monthEnd, dayEnd);
        return sumImage(start, end);
      });
      return ee.ImageCollection(imgs).mean().rename('precip');
    };

    // Observed period images
    const obsOctImg = sumImage(obsOctStart, obsOctEnd);
    const obsJan4Img = sumImage(obsJanStart, obsJanEnd);

    // Baseline climatologies
    const climOctMeanImg = climoMeanImage(10, 1, 11, 1);
    const climJan1to4MeanImg = climoMeanImage(1, 1, 1, 5);

    // Validate pixels (counts) for observed images per region
    const counts = await Promise.all(regions.map(async r => {
      const countOct = await obsOctImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: r.geom,
        scale: ds.scale,
        maxPixels: maxPixels
      }).get('precip').getInfo();
      const countJan = await obsJan4Img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: r.geom,
        scale: ds.scale,
        maxPixels: maxPixels
      }).get('precip').getInfo();
      return { name: r.name, countOct: countOct || 0, countJan: countJan || 0 };
    }));
    if (counts.some(c => c.countOct === 0 || c.countJan === 0)) {
      console.log('Obs Oct imgs:', sizeOct, 'Jan1-4 imgs:', sizeJan);
      counts.forEach(c => console.log(c.name + ' Pixels Oct/Jan:', c.countOct, '/', c.countJan));
      console.log('C2');
      return;
    }

    // Compute region means (mm)
    async function regionMean(img, geom) {
      const val = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: ds.scale,
        maxPixels: maxPixels
      }).get('precip').getInfo();
      return val;
    }

    const results = [];
    for (const r of regions) {
      const oOct = await regionMean(obsOctImg, r.geom);
      const oJan = await regionMean(obsJan4Img, r.geom);
      const cOct = await regionMean(climOctMeanImg, r.geom);
      const cJan = await regionMean(climJan1to4MeanImg, r.geom);

      const vals = [oOct, oJan, cOct, cJan];
      if (vals.some(v => v === null || v === undefined || !isFinite(v) || v < 0)) {
        console.log('C3');
        return;
      }
      const obsTot = oOct + oJan;
      const climTot = cOct + cJan;
      results.push({
        name: r.name,
        oOct, oJan, obsTot,
        cOct, cJan, climTot,
        pixels: counts.find(c => c.name === r.name).countOct // representative
      });
    }

    // Decision
    const aboveCount = results.reduce((acc, r) => acc + (r.obsTot > r.climTot ? 1 : 0), 0);

    // Prints (<=20 lines)
    console.log('Dataset:', ds.key, 'Daily precipitation (mm)');
    console.log('Obs imgs Oct2023:', sizeOct, 'Jan1-4 2024:', sizeJan);
    console.log('Baseline years: 1991-2020 (n=30)');
    results.forEach(r => {
      console.log(
        r.name + ': ' +
        'Oct=' + r.oOct.toFixed(1) + 'mm, ' +
        'Jan1-4=' + r.oJan.toFixed(1) + 'mm, ' +
        'ObsTot=' + r.obsTot.toFixed(1) + 'mm; ' +
        'ClimOct=' + r.cOct.toFixed(1) + 'mm, ' +
        'ClimJan1-4=' + r.cJan.toFixed(1) + 'mm, ' +
        'ClimTot=' + r.climTot.toFixed(1) + 'mm, ' +
        'Pixels=' + r.pixels
      );
    });
    console.log('Regions above climatology:', aboveCount + '/3');
    if (aboveCount >= 2) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    // Likely D: wrong names, syntax, memory issues, etc.
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
